def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    budget = my_status['budget']
    hp = my_status['hp']
    no_water_days = my_status['no_water_days']
    supply = day_context['supply']
    day = day_context['day']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        base = DAILY_SALARY * 0.28
        if hp <= 2 or no_water_days >= 2:
            base = DAILY_SALARY * 0.75
        return max(0, min(budget, base))

    opp_count = len(alive_opponents)
    total_players = opp_count + 1

    pressure_bids = []
    desperation = 0
    failed_yesterday = 0
    for opp in alive_opponents:
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 2:
            desperation += 1
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            pressure_bids.append(bid)
        status = prev.get('status')
        if status is not None and status != 'won':
            failed_yesterday += 1

    expected_share = float(supply) / float(total_players)
    scarcity = expected_share < WATER_REQ

    if pressure_bids:
        highest_prev = max(pressure_bids)
        avg_prev = sum(pressure_bids) / float(len(pressure_bids))
    else:
        highest_prev = 0.0
        avg_prev = 0.0

    if hp <= 2 or no_water_days >= 2:
        bid = max(DAILY_SALARY * 0.9, highest_prev + 2.0)
    elif hp <= 4 or no_water_days == 1:
        bid = max(DAILY_SALARY * 0.62, avg_prev + 1.5)
    else:
        if scarcity:
            bid = DAILY_SALARY * 0.56
        else:
            bid = DAILY_SALARY * 0.34
        if highest_prev >= DAILY_SALARY * 0.85:
            bid = min(bid, DAILY_SALARY * 0.32)
        elif highest_prev > 0:
            bid = max(bid, min(DAILY_SALARY * 0.68, highest_prev + 1.0))

    if desperation >= max(1, opp_count // 2):
        bid += 4.0
    if failed_yesterday >= max(1, opp_count // 2):
        bid += 2.0

    if day >= 8 and hp > 3 and no_water_days == 0:
        bid *= 0.92

    if budget < DAILY_SALARY * 1.2:
        bid = min(bid, budget * 0.72)

    bid = max(0.0, min(float(budget), float(bid)))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    alive_opps = []
    for opp_id, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((opp_id, o))

    if not alive_opps:
        return float(min(my_status.get('budget', 0.0), DAILY_SALARY * 0.4))

    # Extract yesterday bids to infer opponent pressure.
    yesterday_bids = []
    for _, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    my_budget = float(my_status.get('budget', 0.0))
    my_hp = float(my_status.get('hp', 0.0))

    # Estimate how many units of water are likely needed given supply.
    # If supply is tight, we should bid more aggressively.
    tightness = 0.0
    if supply > 0.0:
        tightness = max(0.0, (WATER_REQ - (supply - WATER_REQ)) / max(1.0, float(WATER_REQ)))
    # Clamp tightness to [0,1] roughly.
    if tightness < 0.0:
        tightness = 0.0
    if tightness > 1.0:
        tightness = 1.0

    # If opponent(s) were bidding very high yesterday, they likely need water badly.
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # Aggressive counter if they were near their max willingness.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_hp > 3.0:
                bid = DAILY_SALARY * 0.30
            else:
                bid = DAILY_SALARY * 0.95
            # Add some pressure if supply is tight.
            bid = bid * (1.0 + 0.25 * tightness)
        else:
            # Otherwise, try to secure water at a modest premium.
            bid = max(DAILY_SALARY * 0.50, highest_prev_bid + 1.5)
            bid = bid * (1.0 + 0.15 * tightness)
    else:
        # No trace info: bid based on our hp and likely scarcity.
        if my_hp <= 2.0:
            bid = DAILY_SALARY * 0.90
        else:
            bid = DAILY_SALARY * (0.55 + 0.20 * tightness)

    # Ensure bid is within budget and non-negative.
    if my_budget <= 0.0:
        return 0.0
    if bid < 0.0:
        bid = 0.0
    if bid > my_budget:
        bid = my_budget

    return float(bid)
